const fs = require('fs');
// 在日志里找真实的「自动下线/上线」事件和 notice
for (const day of ['2026-10-04', '2026-10-05', '2026-10-06']) {
  const p = 'D:/ai网站/本地AI/logs/' + day + '.jsonl';
  const lines = fs.readFileSync(p, 'utf8').split('\n');
  const out = [];
  for (const l of lines) {
    if (!l.trim()) continue;
    let j; try { j = JSON.parse(l); } catch (e) { continue; }
    const kind = j.kind || '';
    if (kind === 'notice') {
      out.push((j.t || '').slice(5, 16) + ' [notice] ' + String(j.text || '').replace(/\n/g, ' ').slice(0, 120));
    } else if (kind === 'autooff' || kind === 'autoon') {
      out.push((j.t || '').slice(5, 16) + ' [' + kind + '] ' + JSON.stringify(j).slice(0, 150));
    }
  }
  console.log('==== ' + day + ' (' + out.length + ' 条)');
  console.log(out.join('\n'));
}

const fs = require('fs');
const p = 'D:/ai网站/本地AI/logs/2026-10-06.jsonl';
const lines = fs.readFileSync(p, 'utf8').split('\n');
const kinds = {};
for (const l of lines) {
  if (!l.trim()) continue;
  let j; try { j = JSON.parse(l); } catch (e) { continue; }
  const k = j.kind || '(无kind)';
  kinds[k] = (kinds[k] || 0) + 1;
}
console.log(kinds);
// 找包含「下线」的任意行
const out = [];
for (const l of lines) {
  if (l.includes('下线')) {
    let j; try { j = JSON.parse(l); } catch (e) { continue; }
    const s = JSON.stringify(j).replace(/\n/g, ' ');
    out.push((j.t || '').slice(5, 16) + ' [' + (j.kind || '?') + '] ' + s.slice(0, 200));
  }
}
console.log('含「下线」的行：' + out.length);
console.log(out.slice(0, 20).join('\n'));

